<?php
 namespace Pterodactyl\Services\Dezerx; use Pterodactyl\Models\Egg; use Pterodactyl\Models\User; use Pterodactyl\Models\Server; use Pterodactyl\Models\Dezerx\FreeServer; use Pterodactyl\Repositories\Wings\DaemonFileRepository; use Pterodactyl\Services\Dezerx\ServerCreate\ServerCreate; use Pterodactyl\Services\Servers\ReinstallServerService; use Pterodactyl\Services\Servers\StartupModificationService; class EggSwitcher { public function __construct( private readonly StartupModificationService $startup, private readonly ReinstallServerService $reinstall, private readonly DaemonFileRepository $files, ) { } public function targets(Server $server): array { $allowed = $this->allowed($server); if ($allowed === []) { return []; } return Egg::query() ->with('nest') ->whereIn('uuid', $allowed) ->where('id', '!=', $server->egg_id) ->orderBy('name') ->get() ->map(fn (Egg $egg) => [ 'uuid' => $egg->uuid, 'name' => $egg->name, 'description' => (string) $egg->description, 'nest' => (string) ($egg->nest?->name ?? ''), 'images' => array_values((array) $egg->docker_images), ]) ->values() ->all(); } public function offered(?Server $server = null): int { if ($server !== null) { $allowed = $this->allowed($server); } elseif (EggRules::active()) { $allowed = array_merge(...array_column(EggRules::all(), 'allowed')); } else { $allowed = (array) (Addons::get(Addons::EGG_SWITCHER)['targets'] ?? []); } return $allowed === [] ? 0 : Egg::query()->whereIn('uuid', $allowed)->count(); } public function target(string $uuid, Server $server): ?Egg { $allowed = $this->allowed($server); if (!in_array($uuid, $allowed, true)) { return null; } return Egg::query()->where('uuid', $uuid)->first(); } public function forced(): array { $config = Addons::get(Addons::EGG_SWITCHER); return [ 'startup' => ($config['switch_startup'] ?? '') !== '0', 'reinstall' => ($config['switch_reinstall'] ?? '') !== '0', 'wipe' => ($config['switch_wipe'] ?? '') === '1', ]; } private function allowed(Server $server): array { $allowed = EggRules::active() ? EggRules::allowedFor($server->egg?->uuid) : array_values(array_map('strval', (array) (Addons::get(Addons::EGG_SWITCHER)['targets'] ?? []))); if (FreeServer::query()->where('server_id', $server->id)->exists()) { $allowed = array_values(array_intersect($allowed, array_map('strval', (array) ServerCreate::setting('eggs')))); } return $allowed; } public function blocked(Server $server, ?User $user = null): ?string { if (Demo::is($user)) { return Demo::REFUSAL; } if ($server->isSuspended()) { return 'This server is suspended.'; } if ($server->transfer !== null) { return 'This server is being transferred to another node.'; } if ($server->status === Server::STATUS_INSTALLING) { return 'This server is installing already.'; } if ($server->status === Server::STATUS_RESTORING_BACKUP) { return 'This server is restoring a backup.'; } return null; } public function switch(Server $server, Egg $egg, bool $startup = true, bool $reinstall = true, bool $wipe = false): Server { $environment = []; foreach ($egg->variables as $variable) { $environment[$variable->env_variable] = (string) $variable->default_value; } $images = array_values((array) $egg->docker_images); $this->startup->setUserLevel(User::USER_LEVEL_ADMIN)->handle($server, [ 'egg_id' => $egg->id, 'startup' => $startup ? (string) $egg->startup : (string) $server->startup, 'docker_image' => $images[0] ?? $server->image, 'environment' => $environment, 'skip_scripts' => false, ]); $server = $server->refresh(); if (!$reinstall) { return $server; } if ($wipe) { $this->wipe($server); } return $this->reinstall->handle($server); } private function wipe(Server $server): void { $names = array_values(array_filter(array_map( fn ($entry) => (string) ($entry['name'] ?? ''), $this->files->setServer($server)->getDirectory('/'), ), fn (string $name) => $name !== '')); if ($names !== []) { $this->files->setServer($server)->deleteFiles('/', $names); } } } 